xpath.script:
function previewAvatar(input) {
    if (input.files && input.files[0]) {
        var reader = new FileReader();
        reader.onload = function(e) {
            document.getElementById('avatar_preview').src = e.target.result;
        }
        reader.readAsDataURL(input.files[0]);
    }
}

div.script:
function filterJobsDropdown(input, type) {
    const filter = input.value.toUpperCase();
    const items = document.getElementsByClassName(type + '-item');
    for (let i = 0; i < items.length; i++) {
        const label = items[i].getElementsByTagName('label')[0];
        const txtValue = label.textContent || label.innerText;
        items[i].style.display = txtValue.toUpperCase().indexOf(filter) > -1 ? '' : 'none';
    }
}

function updateJobsFilters() {
    const companyCheckboxes = document.querySelectorAll('.jobs-company-checkbox:checked');
    const companyIds = Array.from(companyCheckboxes).map(cb => cb.value);
    document.getElementById('jobs_company_ids_input').value = companyIds.join(',');
    document.getElementById('jobs_company_label').textContent = companyIds.length > 0 ? 'נבחרו ' + companyIds.length + ' חברות' : 'כל החברות';

    const jobCheckboxes = document.querySelectorAll('.jobs-job-checkbox:checked');
    const jobIds = Array.from(jobCheckboxes).map(cb => cb.value);
    document.getElementById('jobs_job_ids_input').value = jobIds.join(',');
    document.getElementById('jobs_job_label').textContent = jobIds.length > 0 ? 'נבחרו ' + jobIds.length + ' משרות' : 'כל המשרות';
}

function filterDropdown(input, type) {
    const filter = input.value.toUpperCase();
    const items = document.getElementsByClassName(type + '-item');
    for (let i = 0; i < items.length; i++) {
        const label = items[i].getElementsByTagName('label')[0];
        const txtValue = label.textContent || label.innerText;
        items[i].style.display = txtValue.toUpperCase().indexOf(filter) > -1 ? '' : 'none';
    }
}

function updateFilters() {
    const companyCheckboxes = document.querySelectorAll('.company-checkbox:checked');
    const companyIds = Array.from(companyCheckboxes).map(cb => cb.value);
    document.getElementById('company_ids_input').value = companyIds.join(',');
    document.getElementById('company_label').textContent = companyIds.length > 0 ? 'נבחרו ' + companyIds.length + ' חברות' : 'כל החברות';

    const jobCheckboxes = document.querySelectorAll('.job-checkbox:checked');
    const jobIds = Array.from(jobCheckboxes).map(cb => cb.value);
    document.getElementById('job_ids_input').value = jobIds.join(',');
    document.getElementById('job_label').textContent = jobIds.length > 0 ? 'נבחרו ' + jobIds.length + ' משרות' : 'כל המשרות';
}
